QUIZ='''
// Only the two-choice activity lives locally; the central deck owns all navigation.
(() => {
 const pairs=new Map();
 document.querySelectorAll('[data-pair]').forEach(s=>{let a=pairs.get(s.dataset.pair)||[];a.push(s);pairs.set(s.dataset.pair,a)});
 // Balance A/B across the whole lesson, then shuffle; avoid long same-letter runs.
 const randomIndex=n=>{const limit=256-256%n;let x;do{x=crypto.getRandomValues(new Uint8Array(1))[0]}while(x>=limit);return x%n};
 let positions;
 do {
   positions=Array.from({length:pairs.size},(_,i)=>i<Math.ceil(pairs.size/2)?0:1);
   for(let i=positions.length-1;i>0;i--){const j=randomIndex(i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
 } while(positions.some((x,i)=>i>=2&&x===positions[i-1]&&x===positions[i-2]));
 let questionIndex=0;
 pairs.forEach(members=>{
   const flip=positions[questionIndex++];
   members.forEach(slide=>{const box=slide.querySelector('.choices');if(flip)box.append(box.firstElementChild);[...box.children].forEach((b,i)=>b.querySelector('.letter').textContent=i?'B':'A')});
   const question=members.find(s=>!s.classList.contains('reveal'));
   question.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>{
     members.forEach(slide=>slide.querySelectorAll('.choice').forEach(b=>{const chosen=b.dataset.option===button.dataset.option;b.classList.toggle('selected',chosen);if(!b.disabled)b.setAttribute('aria-pressed',String(chosen))}));
     question.querySelector('.status').textContent='הבחירה סומנה. הסבירו מדוע; עברו לשקף הבא לתשובה לדוגמה.';
   }));
 });
})();
'''

def svg(kind):
    if kind=='count':
        shapes='<circle cx="600" cy="315" r="125" fill="#ffc857"/><path d="M0 430 Q300 290 600 430 T1200 430 V650 H0Z" fill="#163c55"/><path d="M0 510 Q300 410 600 510 T1200 510 V650 H0Z" fill="#0c273f"/>'
    else:
        shapes='<path d="M580 650 Q640 450 550 320 L325 95" fill="none" stroke="#ffc857" stroke-width="55"/><path d="M570 370 Q750 240 900 95" fill="none" stroke="#a98cff" stroke-width="55"/>'
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 650"><defs><radialGradient id="g"><stop stop-color="#164364"/><stop offset="1" stop-color="#07111f"/></radialGradient></defs><rect width="1200" height="650" fill="url(#g)"/>{shapes}<g fill="#4ee5ff" opacity=".5">'+''.join(f'<circle cx="{x}" cy="{y}" r="3"/>' for x,y in [(80,80),(180,160),(320,60),(970,140),(1080,50),(720,70)])+'</g></svg>'

def build(slug,title,author,items,kind):
    out=BASE/slug;out.mkdir(exist_ok=True)
    (out/'assets').mkdir(exist_ok=True)
    (out/'assets/pause.svg').write_text(svg(kind))
    slides=[];notes=[]
    def add(body,section='Review',cls='',pair=None):
        num=len(slides)+1
        slides.append(f'<section class="slide {cls}" data-section="{section}"'+(f' data-pair="{pair}"' if pair else '')+f'><div class="frame en">{body}</div></section>')
        return num
    def meta(label):return f'<div class="slide-meta"><p class="eyebrow">{e(label)}</p></div>'
    add(meta('GRADE 10 · LITERATURE · REVISION')+f'<h1 class="cover-title">{title}</h1><p class="cover-sub">{author}</p><p class="instruction">Read → choose → explain → improve.</p><p class="level">חזרה והכנה לבגרות · A2–B1 · שתי תשובות לבחירה</p><p class="level">שאלות תרגול מקוריות — אינן שאלות רשמיות של בחינה</p>','Review','cover transition')
    summary= [('A day well spent','One kind act, word, or glance can comfort someone.'),('A day worse than lost','We have missed the chance to help anyone.')] if kind=='count' else [('The choice','A traveler must choose between two similar roads.'),('The future story','He imagines how he will describe this choice many years later.')]
    add(meta('THE POEM IN TWO IDEAS')+'<h2 class="question">What is the poem about?</h2><div class="map">'+''.join(f'<div><strong>{a}</strong>{b}</div>' for a,b in summary)+'</div><p class="prompt-he">הסבירו לבן הזוג את ההבדל בין שני הרעיונות.</p>')
    vocab=[('deed','an action'),('ease','make pain or worry less'),('glance','a quick look'),('well spent','used in a good way')] if kind=='count' else [('diverged','went in different directions'),('undergrowth','plants below the trees'),('claim','a reason to be chosen'),('hence','from now')]
    add(meta('WORDS WE NEED')+'<h2 class="question">Use these words in your answers.</h2><div class="map">'+''.join(f'<div><strong>{a}</strong>{b}</div>' for a,b in vocab)+'</div>')
    add(meta('BUILD A STRONG ANSWER')+'<h2 class="question">Answer + evidence + explanation</h2><p class="instruction">Give a direct answer.<br>Add a detail from the poem.<br>Explain the connection with <mark class="connector">because</mark>.<br>Use <mark class="connector">for example</mark> for an example and <mark class="connector">however</mark> for a contrast.</p><p class="prompt-he">בכל שאלה: קראו, בחרו A או B, ונמקו. הבחירה אינה חושפת את התשובה; היא מופיעה בשקף הבא.</p>')
    for i,(q,good,bad,model,why) in enumerate(items,1):
        section='Understand' if i<=6 else 'Explain' if i<=12 else 'Write'
        pair=f'q{i}'
        core=meta(f'{section.upper()} · QUESTION {i} / 20')+f'<h2 class="question">{e(q)}</h2>'
        for reveal in [False,True]:
            choices='<div class="choices">'+''.join(f'<button class="choice'+(' correct' if reveal and key=='good' else '')+f'" data-option="{key}" '+('disabled' if reveal else 'aria-pressed="false"')+f'><span class="letter">{letter}</span><span>{highlighted(text)}</span></button>' for key,letter,text in [('good','A',good),('bad','B',bad)])+'</div>'
            answer='<div class="answer-slot"><p class="answer-label">A possible answer</p><p class="possible-answer">'+highlighted(model)+'</p></div>'
            instruction='השוו למודל: איזו ראיה מחזקת אותו? שימו לב למילות הקישור בצהוב.' if reveal else ('בחרו את התשובה המבוססת יותר ונמקו.' if i in [16,18,20] else 'בחרו תשובה ונמקו בעזרת פרט מן השיר.')
            n=add(core+choices+f'<p class="prompt-he">{instruction}</p><div class="status" aria-live="polite"></div>'+answer,section,('qa reveal' if reveal else 'qa')+(' transition' if i in [1,7,13] and not reveal else ''),pair)
            notes.append({'slide':n,'question':i,'type':'answer' if reveal else 'question','prompt':q,'model':model if reveal else None,'teacher_note':why if reveal else 'אפשרו חשיבה עצמאית, הצבעה כיתתית והסבר של שתי האפשרויות. לאחר מכן עברו לשקף הבא.'})
        if i in [4,9,14]:
            add(meta('A MOMENT TO RESET')+'<img class="break-art" src="assets/pause.svg" alt="'+('A warm sun above blue hills' if kind=='count' else 'Two glowing paths dividing in a dark wood')+'"><p class="level en">'+('Small acts. Warm hearts.' if kind=='count' else 'Two paths. One choice.')+'</p>',section,'pause')
    original='count-that-day-lost' if kind=='count' else 'the-road-not-taken-review'
    add(meta('EXIT TICKET')+'<h2 class="question">Now write your own answer.</h2><p class="instruction">'+('Explain how one small act can make a day well spent.' if kind=='count' else 'Explain why the speaker cannot be sure about his choice.')+'</p><p class="instruction">Use one detail from the poem and two suitable linking words. Aim for 3–5 clear sentences.</p><p class="prompt-he">בדקו: עניתי לשאלה? הבאתי ראיה? הסברתי? מילות הקישור מתאימות?</p>'+f'<div class="resource-links"><a href="../{original}/">Open the original poem lesson</a></div>','Write','finish')
    assert len(slides)==48
    nav=''.join(f'<button data-jump="{x}">{x}</button>' for x in ['Review','Understand','Explain','Write'])
    page=f'''<!doctype html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Interactive Revision · Grade 10</title><meta name="theme-color" content="#07111f"><link rel="stylesheet" href="../../../shared/deck/standard.css?v=20261005"><style>{STYLE}</style></head><body class="revision"><a class="home" href="../library/" aria-label="Back to Grade 10">⌂</a><nav class="section-nav" aria-label="Lesson sections">{nav}</nav><main class="stage">{''.join(slides)}</main><nav class="nav" aria-label="Slide navigation"><div class="nav-group"><button data-step="-1" aria-label="Previous slide">←</button><button data-step="1" aria-label="Next slide">→</button></div><output id="counter" class="progress"></output></nav><div class="progress-track"><div class="progress-fill"></div></div><script src="activity.js?v=20261011-balanced"></script><script src="../../../shared/deck/standard.js?v=20261005"></script></body></html>'''
    (out/'index.html').write_text(page)
    (out/'activity.js').write_text(QUIZ)
    (out/'teacher-notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2))
    sources='https://americanliterature.com/author/george-eliot/poem/count-that-day-lost' if kind=='count' else 'https://poets.org/poem/road-not-taken'
    lines=[f'# {title} — תסריט למורה','', '48 שקפים · כיתה י׳ · A2–B1 · 20 שאלות ושקפי תשובה נפרדים.', '', 'סדר האפשרויות מתחלף אקראית בכל פתיחה ונשמר בזוג השאלה והתשובה. אין להסתמך על אות תשובה קבועה. הבגרות דורשת ניסוח עצמאי; הבחירה הכיתתית היא שלב בדרך אליו. כל השאלות מקוריות לתרגול, ואינן מובאות מבחינה רשמית.', '', 'תשובות פתוחות עשויות לקבל ניסוחים ופרשנויות אחרים, בתנאי שהן רלוונטיות ומבוססות. בשאלות דעה הבדיקה עוסקת בנימוק ובקשר לשיר, לא בדעה אחת נכונה.', '',f'מקור טקסט השיר: {sources}','', 'תאריך יצירה: יום ראשון, ל׳ בתשרי תשפ״ז (11.10.2026).', '']
    for i,item in enumerate(items,1):
        q,good,bad,model,why=item
        lines += [f'## שאלה {i}',q,'',f'אפשרות מבוססת: {good}',f'אפשרות חלשה: {bad}','',f'תשובה לדוגמה: {model}','',why,'']
    (out/'teacher-script.md').write_text('\n'.join(lines))
    return out

if __name__=='__main__':
    build('count-that-day-lost-revision','Count That Day Lost','George Eliot',COUNT,'count')
    build('the-road-not-taken-revision','The Road Not Taken','Robert Frost',ROAD,'road')
